const rows = $input.all().map(item => item.json);

function parsePriceNums(str) {
  if (!str) return [];
  const isUSD = /\$/.test(str);
  const nums = (String(str).replace(/,/g, '').match(/\d+(\.\d+)?/g) || []).map(Number);
  return isUSD ? nums.map(n => n * 280) : nums; // rough USD->PKR so all prices bucket consistently
}
function priceBucket(str) {
  const nums = parsePriceNums(str);
  if (!nums.length) return 'No price';
  const maxN = Math.max(...nums);
  if (maxN < 5000) return 'Budget';
  if (maxN <= 20000) return 'Mid-range';
  return 'Premium';
}
function sourceName(src) { return (src || '').split(' - ')[0].trim(); }
function sourceUrl(src) { return (src || '').split(' - ')[1] || '#'; }
function sourceType(name) {
  const n = (name || '').toLowerCase();
  if (n.includes('etsy') || n.includes('daraz')) return 'Marketplace';
  if (n.includes('instagram') || n.includes('woven')) return 'Social';
  if (n.includes('gul ahmed')) return 'Brand site';
  if (n.includes('khoob')) return 'Local retailer';
  if (n.includes('architectural digest')) return 'Editorial';
  return 'Other';
}

const items = rows.map(r => ({
  kw: r.Keyword,
  insight: r.Insight,
  price: r.Price,
  bucket: priceBucket(r.Price),
  sourceName: sourceName(r.Source),
  sourceUrl: sourceUrl(r.Source),
  date: r.Date
}));

const total = items.length;
const withPrice = items.filter(i => i.bucket !== 'No price').length;
const sourceCount = new Set(items.map(i => i.sourceName)).size;
const lastDate = rows.length ? new Date(rows[rows.length - 1].Date).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) : '';

const cardsHtml = items.map((d, i) => {
  const tierClass = 'tier-' + d.bucket.toLowerCase().replace(' ', '-');
  return `
    <div class="card" data-price="${d.bucket}" style="animation-delay:${0.05 * i}s">
      <span class="idx">0${i + 1}</span>
      <div class="kw">${d.kw}</div>
      <div class="insight">${d.insight}</div>
      <div class="price-row">
        <span class="price-label">Price signal &middot; ${d.bucket}</span>
        <span class="price-tag ${tierClass}"><span class="dot"></span>${d.price}</span>
        <a class="source" href="${d.sourceUrl}" target="_blank" rel="noopener">${d.sourceName}<span class="arrow">↗</span></a>
      </div>
    </div>`;
}).join('');

const tierOrder = ['Budget', 'Mid-range', 'Premium', 'No price'];
const tierColorMap = { 'Budget': '#5C6E4F', 'Mid-range': '#B08A2E', 'Premium': '#B4502B', 'No price': '#8B5E6B' };
const tierCounts = {};
items.forEach(d => { tierCounts[d.bucket] = (tierCounts[d.bucket] || 0) + 1; });
const tierLabels = tierOrder.filter(t => tierCounts[t]);
const tierValues = tierLabels.map(t => tierCounts[t]);
const tierColors = tierLabels.map(t => tierColorMap[t]);

const typeCounts = {};
items.forEach(d => { const t = sourceType(d.sourceName); typeCounts[t] = (typeCounts[t] || 0) + 1; });
const typeLabels = Object.keys(typeCounts);
const typeValues = Object.values(typeCounts);
const typePalette = ['#B4502B', '#5C6E4F', '#B08A2E', '#7A8CA3', '#8B5E6B', '#6B6155'];
const typeColors = typeLabels.map((_, i) => typePalette[i % typePalette.length]);

// ---- price trend over time (groups by run date) ----
const byDate = {};
items.forEach(d => {
  const nums = parsePriceNums(d.price);
  if (!nums.length || !d.date) return;
  const dayKey = String(d.date).slice(0, 10); // YYYY-MM-DD
  const max = Math.max(...nums);
  if (!byDate[dayKey]) byDate[dayKey] = [];
  byDate[dayKey].push(max);
});
const trendDateKeys = Object.keys(byDate).sort();
const trendLabels = trendDateKeys.map(dt => {
  const d = new Date(dt);
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short' });
});
const trendValues = trendDateKeys.map(dt => Math.round(byDate[dt].reduce((a, b) => a + b, 0) / byDate[dt].length));

// ---- price range scatter (floor vs ceiling per keyword) ----
const scatterPoints = items.map(d => {
  const nums = parsePriceNums(d.price);
  if (!nums.length) return null;
  return { x: Math.min(...nums), y: Math.max(...nums), kw: d.kw, bucket: d.bucket };
}).filter(Boolean);
const scatterTierColorMap = { 'Budget':'#5C6E4F', 'Mid-range':'#B08A2E', 'Premium':'#B4502B', 'No price':'#8B5E6B' };
const scatterTiers = [...new Set(scatterPoints.map(p => p.bucket))];
const scatterDatasets = scatterTiers.map(tier => ({
  label: tier,
  points: scatterPoints.filter(p => p.bucket === tier).map(p => ({ x: p.x, y: p.y, kw: p.kw })),
  color: scatterTierColorMap[tier]
}));

const filterButtons = ['All ' + total, ...tierLabels].map((label, i) => {
  const f = i === 0 ? 'all' : tierLabels[i - 1];
  return `<button class="filt-btn ${i === 0 ? 'active' : ''}" data-f="${f}">${label}</button>`;
}).join('');

