    plugins: { legend: { display: false }, tooltip: { callbacks: { label: c => 'Rs ' + c.raw.toLocaleString() } } },
    scales: {
      y: { beginAtZero: false, ticks: { callback: v => 'Rs ' + v.toLocaleString() }, grid: { color: 'rgba(36,31,26,0.08)' } },
      x: { grid: { display: false } }
    }
  }
});

buildLegend(document.getElementById('scatterLegend'), ${JSON.stringify(scatterDatasets.map(d => d.label))}, ${JSON.stringify(scatterDatasets.map(d => d.color))});
new Chart(document.getElementById('scatterChart'), {
  type: 'scatter',
  data: {
    datasets: ${JSON.stringify(scatterDatasets.map(d => ({ label: d.label, data: d.points, backgroundColor: d.color, pointRadius: 7, pointHoverRadius: 10 })))}
  },
  options: {
    plugins: {
      legend: { display: false },
      tooltip: { callbacks: { label: c => c.raw.kw + ': Rs ' + c.raw.x.toLocaleString() + ' – Rs ' + c.raw.y.toLocaleString() } }
    },
    scales: {
      x: { title: { display: true, text: 'Price floor (PKR)' }, ticks: { callback: v => 'Rs ' + v.toLocaleString() }, grid: { color: 'rgba(36,31,26,0.08)' } },
      y: { title: { display: true, text: 'Price ceiling (PKR)' }, ticks: { callback: v => 'Rs ' + v.toLocaleString() }, grid: { color: 'rgba(36,31,26,0.08)' } }
    }
  }
});

document.querySelectorAll('.filt-btn').forEach(btn=>{
  btn.addEventListener('click', ()=>{
    document.querySelectorAll('.filt-btn').forEach(b=>b.classList.remove('active'));
    btn.classList.add('active');
    const f = btn.dataset.f;
    document.querySelectorAll('.card').forEach(c=>{
      c.classList.toggle('hidden', f !== 'all' && c.dataset.price !== f);
    });
  });
});
</script>
